120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        // The effective registration date (supplied, or the server date when omitted) must fall on
124	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
125	        // registration date — the stored value, the per-day limit below and the membership number —
126	        // uses this adjusted date.
127	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
128	        owner.setRegistrationDate(effectiveDate);
129	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
130	        // further creates for that day with 429 Too Many Requests.
131	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
132	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
136	        // for its registration date, signalling a bulk-signup surge.
137	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
138	        // Per-city capacity: a city that already holds the maximum number of owners is full.
139	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        // The household id is derived deterministically on the owner itself (see
143	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
144	        // last name and postcode share it automatically — no linking step and no ordering to manage.
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
147	        // (normalized telephone | email-or-empty | householdId) equals an existing owner's. A
148	        // truly identical record is always rejected, independent of sharesHousehold.
149	        if (this.clinicService.isIdentityKeyInUse(owner)) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        // Household duplicate: another owner already belongs to this (last name, postcode)
153	        // household. Reject with 409 unless the caller declares the shared household via
154	        // sharesHousehold, which bypasses the block and creates this owner as a declared member.
155	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
156	        if (householdInUse && !sharesHousehold) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        // Soft "possible duplicate" detection: an existing owner shares this owner's last name and
160	        // postcode with a different telephone. A declared household member (sharesHousehold on an
161	        // in-use household) is an intentional share, not a suspected duplicate, so it is not
162	        // flagged; otherwise the create still proceeds, flagged with possibleDuplicate=true and
163	        // possibleDuplicateOf set to the matching owner id.
164	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
165	            ? null
166	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
167	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
168	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
169	        owner.setNamesakeCount(
170	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
