239	    public void saveOwner(Owner owner) throws DataAccessException {
240	        if (owner.getCustomerCode() == null) {
241	            owner.setCustomerCode(generateCustomerCode(owner));
242	        }
243	        ownerRepository.save(owner);
244	
245	    }
246	
247	    /**
248	     * Build a {@code customerCode} of the form {@code <REGION>-<HASH8>}: the region code derived
249	     * from the owner's postcode (see {@link Regions#forPostcode}), a hyphen, and {@code HASH8} —
250	     * the first eight upper-case hex characters of the SHA-256 of the owner's normalized telephone
251	     * concatenated with its last name (e.g. {@code NSW-3F5A9C2E}). The identity carries no sequence
252	     * number, so it depends only on the owner's own postcode, telephone and last name.
253	     */
254	    private String generateCustomerCode(Owner owner) {
255	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
256	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
257	        return Regions.forPostcode(owner.getPostcode()) + "-" + hash8(telephone + lastName);
258	    }
259	
260	    /**
261	     * The first eight upper-case hex characters (the first four bytes) of the SHA-256 of
262	     * {@code value}, the {@code HASH8} segment of a {@code customerCode}.
263	     */
264	    private static String hash8(String value) {
265	        try {
266	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
267	            StringBuilder sb = new StringBuilder(8);
268	            for (int i = 0; i < 4; i++) {
269	                sb.append(String.format("%02X", digest[i]));
270	            }
271	            return sb.toString();
272	        }
273	        catch (NoSuchAlgorithmException e) {
274	            throw new IllegalStateException("SHA-256 not available", e);
275	        }
276	    }
