319	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
320	        String normalizedLastName = normalizeForComparison(owner.getLastName());
321	        String postcode = owner.getPostcode();
322	        if (normalizedLastName == null || postcode == null) {
323	            return null;
324	        }
325	        String telephone = owner.getTelephone();
326	        return ownerRepository.findAll().stream()
327	            .filter(existing -> existing.getId() != null)
328	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName())))
329	            .filter(existing -> postcode.equals(existing.getPostcode()))
330	            .filter(existing -> telephone == null
331	                ? existing.getTelephone() != null
332	                : !telephone.equals(existing.getTelephone()))
333	            .map(Owner::getId)
334	            .min(Integer::compareTo)
335	            .orElse(null);
336	    }
