362	    @Override
363	    @Transactional(readOnly = true)
364	    public int countOwnersRegisteredOn(LocalDate date) throws DataAccessException {
365	        if (date == null) {
366	            return 0;
367	        }
368	        return (int) ownerRepository.findAll().stream()
369	            .filter(existing -> date.equals(existing.getRegistrationDate()))
370	            .count();
371	    }
372	
373	    @Override
374	    @Transactional(readOnly = true)
375	    public Collection<Visit> findVisitsByPetId(int petId) {
376	        return visitRepository.findByPetId(petId);
377	    }
378	
379	    @Override
380	    @Transactional(readOnly = true)
381	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
382	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
383	    }
384	
385	    private <T> T findEntityById(Supplier<T> supplier) {
386	        try {
387	            return supplier.get();
388	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
389	            // Just ignore not found exceptions for Jdbc/Jpa realization
390	            return null;
391	        }
392	    }
393	
394	}
